// Generated by Suite Builder from a crawl of the site. Gets the cookie banner out of the way.
// EDIT RULES: edit only inside YOURS blocks; regenerating keeps them and rewrites the rest of this file.
import { matchesOf, pageDocument } from './Find';
import { byCss, element, type Locator, type PageElement } from './PageElement';
import { shared } from './Shared';

/**
 * Cypress starts every test with no cookies, so the cookie banner is back in every test and can
 * cover what a test clicks. Every page object's open() calls accept() once per test: it clicks the
 * banner's accept button (the site then remembers the choice for the rest of the test), with its own
 * short time limit, and says what happened. It never fails a test: if the banner can't be accepted,
 * the test goes on, and a click the banner blocks fails with Cypress's own message.
 */
export const CookieBanner = {
  /** The accept button the crawl saw on this site; null when it saw none. */
  SITE_BUTTON: null as Locator | null,
  /** Accept buttons of common consent tools. */
  KNOWN_BUTTONS: byCss('#onetrust-accept-btn-handler, #CybotCookiebotDialogBodyLevelButtonLevelOptinAllowAll, #CybotCookiebotDialogBodyButtonAccept, #didomi-notice-agree-button, #truste-consent-button, [data-testid="uc-accept-all-button"], .cky-btn-accept, #wt-cli-accept-all-btn, #cookie_action_close_header, .cmplz-btn.cmplz-accept, #cn-accept-cookie, #axeptio_btn_acceptAll, [data-cookiefirst-action="accept"], .osano-cm-accept-all, .cc-btn.cc-allow, .fc-cta-consent, .iubenda-cs-accept-btn, #hs-eu-confirmation-button, .brlbs-btn-accept-all, .moove-gdpr-infobar-allow-all'),

  /** Before each test (the support file): the banner is back. */
  reset(): void {
    banner.tried = false;
    banner.accepted = false;
  },

  /** True when accept() clicked the banner's accept button in this test: the banner showed, and took the click. */
  acceptedNow(): boolean {
    return banner.accepted;
  },

  /** The banner's accept button (the site's, or a known tool's) shows now. */
  showingNow(): boolean {
    const site = CookieBanner.SITE_BUTTON ? element('SITE_BUTTON', CookieBanner.SITE_BUTTON) : null;
    return !!(shown(site) ?? shown(element('KNOWN_BUTTONS', CookieBanner.KNOWN_BUTTONS)));
  },

  /**
   * Accepts the banner if one shows, once per test. A banner that comes late (after 4 s:
   * site-a.example's arrives with its analytics, at about 5 s) is waited for three tests running,
   * then no more this run: 4 s a test adds up to twenty minutes over three hundred tests.
   */
  accept(): void {
    if (banner.tried) return;
    banner.tried = true;
    const site = CookieBanner.SITE_BUTTON ? element('SITE_BUTTON', CookieBanner.SITE_BUTTON) : null;
    const known = element('KNOWN_BUTTONS', CookieBanner.KNOWN_BUTTONS);
    const waitFor = site && banner.missed < 3 ? 4000 : 0;
    const end = Date.now() + waitFor;
    const look = (): void => {
      cy.wrap(null, { log: false }).then(() => {
        const button = shown(site) ?? shown(known);
        if (button) {
          banner.missed = 0;
          cy.wrap(button, { log: false }).click({ log: false });
          banner.accepted = true;
          return cy.task('suiteLog', '   cookie banner accepted', { log: false });
        }
        if (Date.now() < end) {
          cy.wait(250, { log: false });
          look();
          return;
        }
        if (!site || waitFor === 0) return;
        banner.missed++;
        const note = banner.missed === 3
          ? '   cookie banner: not shown within 4 s three tests running; not waiting for it again this run'
          : '   cookie banner not shown within 4 s';
        return cy.task('suiteLog', note, { log: false });
      });
    };
    look();
  },

  /**
   * A banner that showed after accept() stopped waiting for it (atos.net's, behind a slow page) covers
   * what a test clicks: clicked away when it shows now, with no wait. Every click calls it first.
   */
  acceptLate(): void {
    cy.wrap(null, { log: false }).then(() => {
      const site = CookieBanner.SITE_BUTTON ? element('SITE_BUTTON', CookieBanner.SITE_BUTTON) : null;
      const button = shown(site) ?? shown(element('KNOWN_BUTTONS', CookieBanner.KNOWN_BUTTONS));
      if (!button) return;
      cy.wrap(button, { log: false }).click({ log: false });
      banner.accepted = true;
      return cy.task('suiteLog', '   cookie banner showed late; accepted', { log: false });
    });
  },

  // ==== YOURS (extras): safe to edit; regenerating keeps what is between these lines ====
  // If this site's banner needs something else (a second "Save" click, say), add it here and call it
  // from accept().
  // ==== END YOURS (extras) ====
};

/** tried, accepted: this test; missed: tests in a row, this run, where the banner the crawl saw did not show within 4 s. One per test window (Shared.ts). */
const banner = shared('cookieBanner', () => ({ tried: false, accepted: false, missed: 0 }));

/** The element if one of its matches is visible now. */
function shown(e: PageElement | null): HTMLElement | undefined {
  const doc = pageDocument();
  return e && doc ? matchesOf(doc, e).find((x) => Cypress.dom.isVisible(x)) : undefined;
}
